entries[77067] = { ["name"] = "Zügel des lodernden Drachen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie Ihr einen lodernden Drachen beschwört. Das ist ein Flugreittier.\nBeschwört einen reitbaren lodernden Drachen oder gibt ihn wieder frei. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Lodernde Drachen zeigen eine endlose Leidenschaft für das Leben und sollen zu den treuesten Reittieren in Azeroth gehören.\"\nBeute von:\nElementiumfragment\nOrt:\nDrachenseele" }
entries[77068] = { ["name"] = "Zügel des Zwielichtboten", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie Ihr einen Zwielichtboten beschwört. Das ist ein Flugreittier.\nBeschwört einen reitbaren Zwielichtboten oder gibt ihn wieder frei. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Die dunkle Magie, die den Zwielichtboten einst kontrollierte, ist nun gebrochen... oder etwa nicht?\"\nErfolg:\nRuhm des Schlachtzüglers der Drachenseele\nKategorie:\nDungeons & Schlachtzüge" }
entries[77069] = { ["name"] = "Erste Dame der Lebensbinderin", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie Ihr die erste Dame der Lebensbinderin beschwört. Das ist ein Flugreittier.\nBeschwört die Erste Dame der Lebensbinderin oder gibt sie wieder frei. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Alexstrasza, der ehemalige Drachenaspekt des Lebens, ist dafür bekannt, eine gütige und geduldige Lehrerin zu sein. Bei ihrer Ausbildung erreichen nur die engagiertesten Schülerinnen den Titel \"Erste Dame der Lebensbinderin\".\"\nBeute von:\nElementiumfragment\nOrt:\nDrachenseele" }
