entries[77528] = { ["name"] = "Trilliumlangstreckenpräzisionsgewehr", ["text"] = "Wird beim Anlegen gebunden\nDistanz Schusswaffe\n6 - 12 Schaden Geschwindigkeit 3.00\n(3.0 Schaden pro Sekunde)\n+3 Beweglichkeit\n+6 Ausdauer\nErhöht Eure kritische Trefferwertung um + 3.\nErhöht Eure Tempowertung um + 4.\n\nPrismatischer Sockel\nSockelbonus: + 0 Beweglichkeit\n\nHaltbarkeit 100 / 100\nVerkaufspreis:" }
entries[77529] = { ["name"] = "Fürst von Schmetternichs Todeszielfernrohr", ["text"] = "Benutzen: Bringt Fürst von Schmetternichs Todeszielfernrohr dauerhaft an einer Distanzwaffe an, sodass manchmal Eure Beweglichkeit 10 Sek. lang um 47 erhöht wird, wenn Ihr Distanzschaden verursacht.\n\nDurch das Anbringen des Fernrohrs an einer Distanzwaffe wird diese seelengebunden. Kann nicht auf Gegenstände über Stufe 320 angewandt werden.\nVerkaufspreis:" }
entries[77530] = { ["name"] = "Geistereisendrachling", ["text"] = "Wird beim Anlegen gebunden\nEinzigartig anlegbar\nSchmuck\nZahnradsockel\nZahnradsockel\nZahnradsockel\nAnlegen: Eure Angriffe haben eine Chance, einen Geistereisendrachling zu beschwören, der 20 Sek. lang an Eurer Seite kämpft. (Procchance: 25%, 1Min. Abklingzeit)\nVerkaufspreis:" }
entries[77531] = { ["name"] = "Verspiegeltes Zielfernrohr", ["text"] = "Benutzen: Bringt ein verspiegeltes Zielfernrohr dauerhaft an einer Distanzwaffe an, sodass manchmal Euer kritischer Trefferwert 10 Sek. lang um 34 erhöht wird, wenn Ihr Distanzschaden verursacht.\n\nDurch das Anbringen des Fernrohrs an einer Distanzwaffe wird diese seelengebunden. Kann nicht auf Gegenstände über Stufe 320 angewandt werden.\nVerkaufspreis:" }
